// embedded n8n/lib/agent_config.js (drift-proof; test asserts equality)
// agent_config.js — Stage 4 central configuration contract (B1).
//
// ONE place resolves the entire agent runtime config from environment variables + safe defaults,
// so the operator never hand-edits a Spreadsheet ID (or any limit/flag) inside individual nodes.
// The orchestrator calls resolveConfig() once and passes the resolved object downstream; every other
// workflow receives config from the request record instead of carrying its own copy.
//
// NO secrets live here or in workflow JSON. Credentials (Google/Telegram/Claude/Apify) stay in the
// n8n credential store; this module only resolves NON-secret runtime settings + the spreadsheet id
// (an id, not a secret) from $env. In a Code node call it as resolveConfig($env) — the harness shims
// $env as {} so the same code runs offline.

function str(v) { return v == null ? '' : String(v).trim(); }
function num(v, d) { const n = Number(v); return isFinite(n) && str(v) !== '' ? n : d; }
function bool(v, d) {
  if (v === true) return true;
  if (v === false) return false;
  const s = str(v).toLowerCase();
  if (s === 'true' || s === 'yes' || s === '1') return true;
  if (s === 'false' || s === 'no' || s === '0') return false;
  return d;
}
function list(v) { return str(v).split(/[\s,;]+/).filter(Boolean); }
// phrase list: split ONLY on ; or | (items may contain spaces, e.g. Avito search queries)
function phraseList(v) { return str(v).split(/[;|]/).map(s => s.trim()).filter(Boolean); }

// Production-safe defaults: fail-closed (approval + source-health required), website-only allowlist,
// LLM features OFF, tight budgets. Everything is overridable by env or explicit override.
const DEFAULTS = {
  spreadsheet_id: '',
  telegram_allowed_user_ids: [],
  max_sources_per_request: 3,
  max_items_per_source: 25,
  max_external_calls: 40,
  source_budget_usd: 0.20,
  llm_budget_usd: 0.50,
  default_region: 'Москва/МО',
  default_niche: 'credit_brokerage',
  source_allowlist: ['website'],
  require_approval: true,
  require_source_health: true,
  enable_llm_planner: false,
  enable_llm_summary: false,
  enable_llm_analysis: true,   // WF08 llm_primary in agent runs (still gated by enable_claude + token + budget)
  // §7 provider unit prices (observed 2026-07: Firecrawl ~1 credit/page, Apify ~$0.01/search, small
  // sonnet call ~$0.01-0.02). Overridable: MS_COST_FIRECRAWL_PAGE_USD / MS_COST_APIFY_SEARCH_USD / MS_COST_CLAUDE_CALL_USD.
  cost_firecrawl_page_usd: 0.01,
  cost_apify_search_usd: 0.01,
  cost_claude_call_usd: 0.02,
  report_data_mode: 'live',
  // ---- Stage 4 free-path / zero-paid-call guards (all fail-closed) -------------------------------------------
  // Telegram conversation is allowed; every PAID external action is OFF by default. The free path runs the full
  // conversation -> plan -> approval -> persistence loop while making zero paid calls. `max_external_calls` (above)
  // is the master kill-switch: 0 means no paid source/LLM call can occur even after approval.
  timezone: 'Europe/Moscow',
  // WF18-CONFIG-001: the Telegram ingress is fail-closed. The bot does NOTHING (no parse, no Sheets, no send)
  // until the operator explicitly sets MS_ENABLE_TELEGRAM=true. WF18 branches on this as a HARD ingress gate.
  enable_telegram: false,
  enable_external_actions: false,   // master switch for any paid collection/analysis
  enable_claude: false,             // Claude (planner/summary) only when explicitly enabled
  enable_apify: false,
  enable_firecrawl: false,
  enable_vk: false,
  // AVITO-BLOCK-001: Avito is an OPTIONAL source that is operator-infra-blocked until a Residential proxy is
  // provisioned on a paid Apify plan (AVITO_SOURCE_QUALITY=BLOCKED_OPTIONAL_OPERATOR_INFRA_PREREQUISITE). The
  // WF09 implementation + tests + evidence stay in the repo, but the bot must NOT offer/plan/select/run Avito
  // for users while blocked. Default OFF => Avito is stripped from the resolved runtime source_allowlist (the
  // one gate every downstream surface derives availability from). RE-ENABLE PATH: set MS_AVITO_ENABLED=true
  // once Residential proxy access exists — nothing is deleted, so re-enabling restores the full Avito path.
  avito_enabled: false,
  // Stage 5: Telegram PUBLIC channel preview collector (t.me/s/<channel>, no per-call fee but still an external
  // fetch — gated like every collector). Distinct from enable_telegram (the bot ingress).
  enable_telegram_collector: false,
  monitoring_enabled: false,
  weekly_digest_enabled: false,
  // Stage 5 MVP source targets (overridable by env; NON-secret). Avito queries are phrases (split on ';').
  avito_queries: ['кредитный брокер Москва', 'помощь в получении кредита Москва', 'кредит под ПТС Москва'],
  telegram_channels: ['mfo_market', 'da_credit', 'broker_Aleksey'],
  vk_communities: ['kredit874', 'da_credit', 'anna_findoctor'],
  // real Moscow competitor sites for the website source (set via MS_WEBSITE_COMPETITOR_URLS; https only)
  // MVP v1 verified Moscow credit-broker competitor sites (live-checked 2026-07-03: помощь в получении
  // кредита / залог / ПТС / рефинансирование / ипотека, все https). MS_WEBSITE_COMPETITOR_URLS overrides.
  website_competitor_urls: ['https://www.lioncredit.ru/', 'https://finardi.ru/', 'https://mkbkfin.ru/']
};

// Map env var -> resolved config. Unknown/blank env falls back to DEFAULTS; explicit overrides win last.
function resolveConfig(env, overrides) {
  env = env || {};
  overrides = overrides || {};
  const allowedUsers = list(env.MS_TELEGRAM_ALLOWED_USER_IDS);
  const allowlist = list(env.MS_SOURCE_ALLOWLIST).map(s => s.toLowerCase());
  const cfg = {
    spreadsheet_id: str(env.MS_SPREADSHEET_ID) || DEFAULTS.spreadsheet_id,
    telegram_allowed_user_ids: (allowedUsers.length ? allowedUsers : DEFAULTS.telegram_allowed_user_ids).map(String),
    max_sources_per_request: num(env.MS_MAX_SOURCES, DEFAULTS.max_sources_per_request),
    max_items_per_source: num(env.MS_MAX_ITEMS_PER_SOURCE, DEFAULTS.max_items_per_source),
    max_external_calls: num(env.MS_MAX_EXTERNAL_CALLS, DEFAULTS.max_external_calls),
    source_budget_usd: num(env.MS_SOURCE_BUDGET_USD, DEFAULTS.source_budget_usd),
    llm_budget_usd: num(env.MS_LLM_BUDGET_USD, DEFAULTS.llm_budget_usd),
    // §7 operator-controlled provider unit prices (cost_model.js) — the ONE place unit prices live.
    cost_firecrawl_page_usd: num(env.MS_COST_FIRECRAWL_PAGE_USD, DEFAULTS.cost_firecrawl_page_usd),
    cost_apify_search_usd: num(env.MS_COST_APIFY_SEARCH_USD, DEFAULTS.cost_apify_search_usd),
    cost_claude_call_usd: num(env.MS_COST_CLAUDE_CALL_USD, DEFAULTS.cost_claude_call_usd),
    default_region: str(env.MS_DEFAULT_REGION) || DEFAULTS.default_region,
    default_niche: str(env.MS_DEFAULT_NICHE) || DEFAULTS.default_niche,
    source_allowlist: allowlist.length ? allowlist : DEFAULTS.source_allowlist.slice(),
    require_approval: bool(env.MS_REQUIRE_APPROVAL, DEFAULTS.require_approval),
    require_source_health: bool(env.MS_REQUIRE_SOURCE_HEALTH, DEFAULTS.require_source_health),
    enable_llm_planner: bool(env.MS_ENABLE_LLM_PLANNER, DEFAULTS.enable_llm_planner),
    enable_llm_summary: bool(env.MS_ENABLE_LLM_SUMMARY, DEFAULTS.enable_llm_summary),
    enable_llm_analysis: bool(env.MS_ENABLE_LLM_ANALYSIS, DEFAULTS.enable_llm_analysis),
    report_data_mode: str(env.MS_REPORT_DATA_MODE) || DEFAULTS.report_data_mode,
    timezone: str(env.MS_TIMEZONE) || DEFAULTS.timezone,
    enable_telegram: bool(env.MS_ENABLE_TELEGRAM, DEFAULTS.enable_telegram),
    enable_external_actions: bool(env.MS_ENABLE_EXTERNAL_ACTIONS, DEFAULTS.enable_external_actions),
    enable_claude: bool(env.MS_ENABLE_CLAUDE, DEFAULTS.enable_claude),
    enable_apify: bool(env.MS_ENABLE_APIFY, DEFAULTS.enable_apify),
    enable_firecrawl: bool(env.MS_ENABLE_FIRECRAWL, DEFAULTS.enable_firecrawl),
    enable_vk: bool(env.MS_ENABLE_VK, DEFAULTS.enable_vk),
    avito_enabled: bool(env.MS_AVITO_ENABLED, DEFAULTS.avito_enabled),
    enable_telegram_collector: bool(env.MS_ENABLE_TELEGRAM_COLLECTOR, DEFAULTS.enable_telegram_collector),
    monitoring_enabled: bool(env.MS_MONITORING_ENABLED, DEFAULTS.monitoring_enabled),
    weekly_digest_enabled: bool(env.MS_WEEKLY_DIGEST_ENABLED, DEFAULTS.weekly_digest_enabled),
    avito_queries: (phraseList(env.MS_AVITO_QUERIES).length ? phraseList(env.MS_AVITO_QUERIES) : DEFAULTS.avito_queries.slice()).slice(0, 3),
    telegram_channels: (list(env.MS_TELEGRAM_CHANNELS).length ? list(env.MS_TELEGRAM_CHANNELS) : DEFAULTS.telegram_channels.slice()).slice(0, 3),
    vk_communities: (list(env.MS_VK_COMMUNITIES).length ? list(env.MS_VK_COMMUNITIES) : DEFAULTS.vk_communities.slice()).slice(0, 3),
    website_competitor_urls: (list(env.MS_WEBSITE_COMPETITOR_URLS).length ? list(env.MS_WEBSITE_COMPETITOR_URLS) : DEFAULTS.website_competitor_urls.slice()).filter(u => /^https:\/\//i.test(u)).slice(0, 3)
  };
  for (const k in overrides) {
    if (Object.prototype.hasOwnProperty.call(overrides, k)) cfg[k] = overrides[k];
  }
  // fail-closed reconciliation: Claude master switch gates the LLM features; the external-actions master switch
  // (or a zero call ceiling) forces the effective paid-call budget to zero so no approval can spend.
  if (!cfg.enable_claude) { cfg.enable_llm_planner = false; cfg.enable_llm_summary = false; cfg.enable_llm_analysis = false; }
  // WF19-LLM-001: there is NO in-graph Claude intent-classifier node in WF18, so the intent router's guarded
  // LLM branch is unreachable by construction. Pin enable_llm_intent=false in the resolved config so the router
  // always resolves deterministically or asks ONE clarification — we never advertise a classification path that
  // cannot run. (The router lib still supports the branch for a future, explicitly-wired classifier.)
  cfg.enable_llm_intent = false;
  cfg.zero_paid_mode = (cfg.enable_external_actions !== true) || (Number(cfg.max_external_calls) <= 0);
  cfg.effective_max_external_calls = cfg.zero_paid_mode ? 0 : Number(cfg.max_external_calls);
  // scope_preview/collector naming alias — one flag, two historical names
  cfg.enable_vk_collector = cfg.enable_vk === true;
  // AVITO-BLOCK-001 (see DEFAULTS.avito_enabled): the ONE canonical Avito gate. While Avito is blocked it is
  // removed from the resolved runtime allowlist AND recorded in cfg.blocked_sources, so the request planner can
  // tell a user who explicitly asks for Avito that it is temporarily unavailable (never a silent drop). Every
  // surface that derives availability from source_allowlist — planner, capability registry, tracked sources,
  // scope preview, refresh policy, per-collector gate — inherits the block from here.
  cfg.avito_enabled = cfg.avito_enabled === true;
  cfg.blocked_sources = [];
  if (!cfg.avito_enabled) {
    cfg.source_allowlist = (cfg.source_allowlist || []).filter(s => String(s).toLowerCase() !== 'avito');
    cfg.blocked_sources.push('avito');
    cfg.avito_block_reason = 'residential_proxy_required';
  }
  // completeness check the orchestrator surfaces in the execution summary — never starts paid work blind
  cfg.missing = [];
  if (!cfg.spreadsheet_id) cfg.missing.push('MS_SPREADSHEET_ID');
  if (!cfg.telegram_allowed_user_ids.length) cfg.missing.push('MS_TELEGRAM_ALLOWED_USER_IDS');
  cfg.config_complete = cfg.missing.length === 0;
  return cfg;
}

function isAllowedUser(cfg, userId) {
  return ((cfg && cfg.telegram_allowed_user_ids) || []).indexOf(String(userId)) >= 0;
}
function sourceAllowed(cfg, source) {
  return ((cfg && cfg.source_allowlist) || []).indexOf(String(source).toLowerCase()) >= 0;
}
// true only when a PAID external action may run: external actions enabled AND a positive call ceiling.
// This is the single fail-closed predicate the orchestrator/monitor consult before any paid call.
function paidCallsAllowed(cfg) {
  return !!(cfg && cfg.enable_external_actions === true && Number(cfg.max_external_calls) > 0);
}
// per-collector gate: paid calls must be globally allowed AND the specific collector enabled AND on the allowlist.
function collectorEnabled(cfg, source) {
  if (!paidCallsAllowed(cfg)) return false;
  const s = String(source).toLowerCase();
  const flag = {
    website: 'enable_firecrawl', firecrawl: 'enable_firecrawl',
    apify: 'enable_apify', avito: 'enable_apify',
    vk: 'enable_vk', vk_community: 'enable_vk',
    telegram: 'enable_telegram_collector', telegram_channel: 'enable_telegram_collector'
  }[s];
  return sourceAllowed(cfg, s) && (flag ? cfg[flag] === true : false);
}
function llmAllowed(cfg) { return !!(cfg && cfg.enable_claude === true && (cfg.enable_llm_planner === true || cfg.enable_llm_summary === true)); }
// machine-readable free-path snapshot for the execution summary / tests.
function freePathStatus(cfg) {
  return {
    zero_paid_mode: !!(cfg && cfg.zero_paid_mode),
    enable_telegram: !!(cfg && cfg.enable_telegram),
    paid_calls_allowed: paidCallsAllowed(cfg),
    llm_allowed: llmAllowed(cfg),
    effective_max_external_calls: cfg ? Number(cfg.effective_max_external_calls) : 0,
    collectors: {
      firecrawl: collectorEnabled(cfg, 'website'), apify: collectorEnabled(cfg, 'apify'),
      vk: collectorEnabled(cfg, 'vk'), avito: collectorEnabled(cfg, 'avito'), telegram: collectorEnabled(cfg, 'telegram')
    }
  };
}
// --- end embedded agent_config ---

// --- node driver ---
var __env=(typeof $env!=='undefined'&&$env)?$env:{};
return [{json:resolveConfig(__env)}];

// embedded n8n/lib/vk_collector.js (drift-proof; test asserts equality)
// vk_collector.js — bounded, production-shaped optional VK PUBLIC community wall collector (Section 6).
//
// Scope (honest): public communities only — resolve by URL / screen name / numeric group id / negative owner id;
// read PUBLIC wall posts; collect new posts since a stored cursor; bounded historical backfill; detect new/edited
// public posts for monitoring. Comments are optional behind a disabled-by-default flag. We NEVER claim private
// groups, private profiles, arbitrary user data, messages, member/audience scraping, or full historical archive.
//
// This module is PURE: it builds the official-API request *descriptors* (params only — never a token, never an
// HTTP call) and PARSES API responses (incl. VK's HTTP-200-with-error-body convention). The access token lives
// only in the n8n credential store; a missing token yields status 'setup_required' (NOT an empty success).
// Self-contained (no cross-require) so it embeds verbatim into the generated workflow. $0, 0 calls from here.

function str(v) { return v == null ? '' : String(v).trim(); }
function low(v) { return str(v).toLowerCase(); }
function num(v) { const n = Number(v); return isFinite(n) ? n : null; }
function arr(v) { return Array.isArray(v) ? v : []; }
function bool(v) { return v === true || v === 'true' || v === 1 || v === '1'; }

// djb2 — stable, dependency-free content hash.
function hash(s) { s = String(s == null ? '' : s); let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0; return 'h' + h.toString(16); }

const PLATFORM = 'vk';
const SOURCE_TYPE = 'vk_community_wall';
const DEFAULT_API_VERSION = '5.199';
// VK API versions we accept (must be configurable + validated — never hardcode one undocumented "current" value).
const SUPPORTED_API_VERSIONS = ['5.131', '5.199', '5.200', '5.201'];

function resolveApiVersion(cfg) {
  cfg = cfg || {};
  const v = str(cfg.vk_api_version) || DEFAULT_API_VERSION;
  return { version: v, valid: SUPPORTED_API_VERSIONS.indexOf(v) >= 0, supported: SUPPORTED_API_VERSIONS };
}

// ---- §6.3 canonical VK source identity ----------------------------------------------------------------------
// Accepts: https://vk.com/example | vk.com/example | @example | example | club123 | public123 | id-less numeric |
// numeric group id "123" | negative owner id "-123". Returns a canonical reference. Resolution of a screen name
// to a numeric community id happens later via groups.getById (offline we keep the screen name as the key).
function normalizeCommunity(raw) {
  let s = str(raw);
  let screen = '', communityId = null;
  s = s.replace(/^https?:\/\//i, '').replace(/^vk\.com\//i, '').replace(/^vk:\/\//i, '').replace(/^@/, '').replace(/\/+$/, '');
  if (/^-?\d+$/.test(s)) {
    communityId = Math.abs(parseInt(s, 10));          // numeric group id or negative owner id
  } else if (/^(club|public|event)(\d+)$/i.test(s)) {
    communityId = parseInt(s.replace(/^(club|public|event)/i, ''), 10);
    screen = low(s);
  } else if (/^[a-z0-9_.]+$/i.test(s)) {
    screen = low(s);
  } else {
    return { ok: false, reason: 'unparseable_vk_ref', input: str(raw) };
  }
  const canonicalScreen = screen || (communityId != null ? 'club' + communityId : '');
  return {
    ok: true, platform: PLATFORM, source_type: SOURCE_TYPE,
    community_id: communityId,                          // may be null until resolved by groups.getById
    screen_name: screen || '',
    owner_id: communityId != null ? -Math.abs(communityId) : null,   // wall.get owner_id for a community is negative
    canonical_url: 'https://vk.com/' + canonicalScreen,
    display_name: '',
    // dedup uses canonical community identity (numeric id if known, else screen name) — NOT the raw input string
    key: SOURCE_TYPE + '::' + (communityId != null ? String(communityId) : screen)
  };
}
function communityKey(identity) { identity = identity || {}; return SOURCE_TYPE + '::' + (identity.community_id != null ? String(identity.community_id) : str(identity.screen_name)); }

// ---- §6.2 credential / config gate --------------------------------------------------------------------------
// A missing token is setup_required (visible, not collected) — never a successful empty collection.
function credentialState(cfg) {
  cfg = cfg || {};
  if (cfg.enable_vk_collector !== true) return { ok: false, status: 'setup_required', reason: 'vk_collector_disabled' };
  if (!cfg.vk_token_present) return { ok: false, status: 'setup_required', reason: 'missing_vk_credential' };
  const ver = resolveApiVersion(cfg);
  if (!ver.valid) return { ok: false, status: 'config_error', reason: 'unsupported_vk_api_version', api_version: ver.version, supported: ver.supported };
  return { ok: true, status: 'configured', api_version: ver.version };
}
function collectorConfig(cfg) {
  cfg = cfg || {};
  return {
    api_version: resolveApiVersion(cfg).version,
    max_posts: num(cfg.vk_max_posts) || 25,
    max_pages: num(cfg.vk_max_pages) || 3,
    page_size: Math.min(100, num(cfg.vk_page_size) || 50),
    lookback_days: num(cfg.vk_lookback_days) || 30,
    comments_enabled: cfg.vk_enable_comments === true,
    max_comments_per_post: num(cfg.vk_max_comments_per_post) || 10,
    max_comment_posts: num(cfg.vk_max_comment_posts) || 8   // D2: bound how many posts we pull comments for per run
  };
}

// ---- §6.4 official API operation descriptors (params only; token injected by n8n credential, NOT here) -------
function resolveRequest(identity, cfg) {
  const ver = resolveApiVersion(cfg).version;
  // groups.getById resolves screen name OR numeric id -> canonical community object
  return { method: 'groups.getById', params: { group_id: str(identity.screen_name) || String(identity.community_id || ''), fields: 'screen_name,name,is_closed,deactivated,members_count,type', v: ver } };
}
function wallRequest(identity, cfg, offset) {
  const c = collectorConfig(cfg);
  return { method: 'wall.get', params: { owner_id: String(identity.owner_id != null ? identity.owner_id : (identity.community_id != null ? -Math.abs(identity.community_id) : '')), count: Math.min(c.page_size, c.max_posts), offset: num(offset) || 0, filter: 'owner', extended: 0, v: c.api_version } };
}
function commentsRequest(identity, post, cfg) {
  const c = collectorConfig(cfg);
  if (!c.comments_enabled) return null;   // disabled by default — never request comments behind the flag
  return { method: 'wall.getComments', params: { owner_id: String(identity.owner_id), post_id: num(post && post.post_id), count: c.max_comments_per_post, need_likes: 0, v: c.api_version } };
}

// ---- error mapping: VK returns errors as HTTP 200 with an `error` body (or a transport error) ----------------
function mapError(resp) {
  resp = resp || {};
  if (resp.error && (resp.error.error_code != null)) {
    const code = num(resp.error.error_code);
    const msg = str(resp.error.error_msg);
    if (code === 5) return { kind: 'token_invalid', retryable: false, setup_required: true, code: code, msg: msg };
    if (code === 6 || code === 29) return { kind: 'rate_limited', retryable: true, setup_required: false, code: code, msg: msg };
    if (code === 15 || code === 203 || code === 7) return { kind: 'access_denied', retryable: false, setup_required: false, code: code, msg: msg };
    if (code === 100 || code === 113 || code === 125) return { kind: 'invalid_request', retryable: false, setup_required: false, code: code, msg: msg };
    return { kind: 'api_error', retryable: false, setup_required: false, code: code, msg: msg };
  }
  if (resp.transport_error) return { kind: 'transport_error', retryable: true, setup_required: false, code: null, msg: str(resp.transport_error) };
  return null;   // no error
}

// ---- §6.4 parse community resolution ------------------------------------------------------------------------
function parseResolution(resp) {
  const err = mapError(resp);
  if (err) return { ok: false, error: err };
  // VK 5.x groups.getById returns { response: { groups: [..] } } or legacy { response: [..] }
  const list = (resp.response && (resp.response.groups || resp.response)) || [];
  const g = arr(list)[0];
  if (!g) return { ok: false, error: { kind: 'not_found', retryable: false, setup_required: false, msg: 'group not found' } };
  if (str(g.deactivated)) return { ok: false, error: { kind: g.deactivated === 'banned' ? 'banned' : 'deleted', retryable: false, setup_required: false, msg: 'group ' + g.deactivated } };
  if (num(g.is_closed) === 1 || num(g.is_closed) === 2) return { ok: false, error: { kind: 'private_group', retryable: false, setup_required: false, msg: 'community is closed/private' } };
  return {
    ok: true,
    community: {
      community_id: num(g.id), screen_name: low(g.screen_name) || ('club' + num(g.id)),
      owner_id: -Math.abs(num(g.id)), display_name: str(g.name),
      canonical_url: 'https://vk.com/' + (low(g.screen_name) || ('club' + num(g.id))),
      members_count: num(g.members_count), type: str(g.type), platform: PLATFORM, source_type: SOURCE_TYPE
    }
  };
}

// ---- §6.5 canonical VK record from a wall post --------------------------------------------------------------
function buildRecord(post, identity, ctx) {
  post = post || {}; identity = identity || {}; ctx = ctx || {};
  const ownerId = num(post.owner_id) != null ? num(post.owner_id) : num(identity.owner_id);
  const postId = num(post.id);
  const editedTs = num(post.edited) || 0;          // unix; 0 = never edited
  const publishedTs = num(post.date) || 0;
  const text = str(post.text);
  const attachments = arr(post.attachments).map(a => ({ type: str(a.type) })); // metadata only — never download files
  const copyHistory = arr(post.copy_history);
  const isRepost = copyHistory.length > 0;
  const counters = {
    likes: num((post.likes || {}).count), comments: num((post.comments || {}).count),
    reposts: num((post.reposts || {}).count), views: num((post.views || {}).count)
  };
  // content hash drives edit detection; includes text + attachment shape + repost source
  const contentHash = hash(text + '|' + attachments.map(a => a.type).join(',') + '|' + (isRepost ? str((copyHistory[0] || {}).id) : ''));
  const canonicalUrl = 'https://vk.com/wall' + ownerId + '_' + postId;
  return {
    agent_request_id: str(ctx.agent_request_id), source_run_id: str(ctx.source_run_id), workflow_run_id: str(ctx.workflow_run_id),
    source_record_id: 'vk_' + ownerId + '_' + postId, owner_user_id: str(ctx.owner_user_id),
    platform: PLATFORM, source_type: SOURCE_TYPE,
    community_id: identity.community_id != null ? identity.community_id : Math.abs(ownerId),
    owner_id: ownerId, post_id: postId,
