  const demandish = /(кредит|займ|ипотек|рефинанс|залог|птс|брокер|отказ|просрочк|долг|банк|деньг|ставк|помог|подскаж|посоветуй|как\s|почему|сколько|можно ли|нужн|ищу|\?)/.test(l);
