  if (f < 0) return true;                       // any group/community author
  identity = identity || {};
  const oid = num(identity.owner_id), cid = num(identity.community_id);
  if (oid != null && f === oid) return true;
  if (cid != null && f === -Math.abs(cid)) return true;
